  `id_pengaju_penelitian` int(11) NOT NULL,
  `unique_code` varchar(10) DEFAULT NULL,
  `surat_permohonan` text DEFAULT NULL,
  `is_processed` char(1) NOT NULL DEFAULT '0',
  `is_upload_protokol` char(1) NOT NULL DEFAULT '0',
  `is_upload_informed_consent` char(1) DEFAULT '0',
  `is_etik_cleared` char(1) DEFAULT '0',
  `created_time` datetime DEFAULT NULL,
  `created_by` varchar(50) DEFAULT NULL,
  `modified_time` datetime DEFAULT NULL,
  `modified_by` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1633 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

