  `intervensi` varchar(255) DEFAULT NULL,
  `tarif` int(11) DEFAULT NULL,
  `medis_nonmedis` varchar(50) DEFAULT NULL,
  `publikasi` varchar(50) DEFAULT NULL,
  `keterangan_publikasi` text DEFAULT NULL,
  `penandatangan_surat` varchar(50) DEFAULT NULL,
  `selesai` tinyint(4) DEFAULT NULL,
  `created` datetime DEFAULT NULL,
  `modified` datetime DEFAULT NULL,
  `file` text DEFAULT NULL,
  `id_surat` varchar(20) DEFAULT NULL,
  `nomor_surat_ruangan` varchar(100) DEFAULT NULL,
  `id_ttd` int(11) DEFAULT NULL,
  `paragraf1` text DEFAULT NULL,
  `paragraf2` text DEFAULT NULL,
